700	
701	// Per-project-group cache of the remote default branch, used to populate the
702	// "Create New Worktree" submenu without doing git I/O while the menu is open.
703	enum DefaultBranchCache {
704	    Pending,
705	    Resolved(Option<RemoteBranchName>),
706	}
707	
708	// Mirrors the behavior of the worktree picker's "Create new worktree" entries.
709	fn create_worktree_in_workspace(
710	    workspace: &Entity<Workspace>,
711	    branch_target: NewWorktreeBranchTarget,
712	    window: &mut Window,
713	    cx: &mut App,
714	) {
715	    workspace.update(cx, |workspace, cx| {
716	        let focused_dock = workspace.focused_dock_position(window, cx);
717	        git_ui_core::worktree_service::handle_create_worktree(
718	            workspace,
719	            &CreateWorktree {
720	                worktree_name: None,
721	                branch_target,
722	            },
723	            window,
724	            focused_dock,
725	            cx,
726	        );
727	    });
728	}
729	
730	/// The sidebar re-derives its entire entry list from scratch on every
731	/// change via `update_entries` → `rebuild_contents`. Avoid adding
732	/// incremental or inter-event coordination state — if something can
733	/// be computed from the current world state, compute it in the rebuild.
734	pub struct Sidebar {
735	    multi_workspace: WeakEntity<MultiWorkspace>,
736	    width: Pixels,
737	    focus_handle: FocusHandle,
738	    filter_editor: Entity<Editor>,
739	    thread_rename_editor: Entity<Editor>,
740	    list_state: ListState,
741	    contents: SidebarContents,
742	    /// The index of the list item that currently has the keyboard focus
743	    ///
744	    /// Note: This is NOT the same as the active item.
745	    selection: Option<usize>,
746	    /// Tracks which sidebar entry is currently active (highlighted).
747	    active_entry: Option<ActiveEntry>,
748	    hovered_thread_index: Option<usize>,
749	    renaming_thread_id: Option<ThreadId>,
750	    /// Threads in the database-backed regeneration path need their own loading
751	    /// state because they do not have a live `agent::Thread` to report it.
752	    regenerating_titles: HashSet<ThreadId>,
753	    /// start_renaming_thread must seed current title into the title editor
754	    /// so this prevents that BufferEdited event from being interpreted as user input.
755	    suppress_next_rename_edit: bool,
756	
757	    /// Updated only in response to explicit user actions (clicking a
758	    /// thread, confirming in the thread switcher, etc.) — never from
759	    /// background data changes. Used to sort the thread switcher popup.
760	    thread_last_accessed: HashMap<ThreadId, DateTime<Utc>>,
761	    terminal_last_accessed: HashMap<TerminalId, DateTime<Utc>>,
762	    thread_switcher: Option<Entity<ThreadSwitcher>>,
763	    _thread_switcher_subscriptions: Vec<gpui::Subscription>,
764	    pending_thread_activation: Option<agent_ui::ThreadId>,
765	    /// Persists live thread statuses across rebuilds so that Running→Completed
766	    /// transitions can be detected even when the group is collapsed (and
767	    /// thread entries are not present in the list).
768	    live_thread_statuses: HashMap<acp::SessionId, (AgentThreadStatus, ThreadId)>,
769	    /// Remembers whether each draft last rendered as empty or with content so
770	    /// that when a draft that was empty gains content again, we refresh
771	    /// its interaction time.
772	    draft_kinds: HashMap<ThreadId, DraftKind>,
773	    view: SidebarView,
774	    restoring_tasks: HashMap<agent_ui::ThreadId, Task<()>>,
775	    recent_projects_popover_handle: PopoverMenuHandle<SidebarRecentProjects>,
776	    project_header_menu_handles: HashMap<usize, PopoverMenuHandle<ContextMenu>>,
777	    project_header_new_thread_menu_handles: HashMap<usize, PopoverMenuHandle<ContextMenu>>,
778	    project_header_menu_ix: Option<usize>,
779	    worktree_default_branches: HashMap<ProjectGroupKey, DefaultBranchCache>,
780	    _subscriptions: Vec<gpui::Subscription>,
781	    _draft_editor_observations: Vec<gpui::Subscription>,
782	    update_task: Option<Task<()>>,
783	    /// For the thread import banners, if there is just one we show "Import
784	    /// Threads" but if we are showing both the external agents and other
785	    /// channels import banners then we change the text to disambiguate the
